<script setup lang="ts">
import {computed,ref} from 'vue';import {useRoute} from 'vue-router';import {Download,Plus,Search} from '@element-plus/icons-vue';import {ElMessage} from 'element-plus';const route=useRoute();const keyword=ref('');const status=ref('全部');const drawer=ref(false);type Row=Record<string,string|number>;const configs:Record<string,{description:string;permission:string;columns:Array<{key:string;label:string}>;rows:Row[]}>= {
 user:{description:'管理消费者账号、员工档案、部门岗位与账号状态。',permission:'user:write',columns:[{key:'id',label:'用户 ID'},{key:'name',label:'姓名 / 账号'},{key:'org',label:'部门 / 岗位'},{key:'role',label:'角色'},{key:'status',label:'状态'},{key:'updated',label:'最近登录'}],rows:[{id:'10001',name:'王晓明 / wangxm',org:'跨境业务部 / 关务专员',role:'员工',status:'正常',updated:'2026-07-13 00:21'},{id:'10002',name:'陈嘉怡 / chenjy',org:'商品中心 / 商品运营',role:'运营人员',status:'正常',updated:'2026-07-12 18:09'},{id:'10003',name:'李先生 / user_li',org:'—',role:'消费者',status:'已停用',updated:'2026-07-08 12:30'}]},
 product:{description:'维护类目、品牌、SPU/SKU、规格、价格、图片、溯源与上下架。',permission:'product:write',columns:[{key:'code',label:'SPU / SKU'},{key:'name',label:'商品名称'},{key:'category',label:'类目'},{key:'price',label:'售价'},{key:'stock',label:'可用库存'},{key:'status',label:'状态'}],rows:[{code:'YGH-FRUIT-001',name:'粤西高州桂味荔枝礼盒',category:'岭南鲜果',price:'¥128.00',stock:186,status:'已上架'},{code:'YGH-SEA-004',name:'挪威冰鲜三文鱼中段',category:'全球生鲜',price:'¥119.00',stock:45,status:'库存预警'},{code:'YGH-HK-002',name:'港式流心奶黄月饼精选装',category:'港味手信',price:'¥168.00',stock:72,status:'已上架'}]},
 inventory:{description:'查看可用、锁定、已售库存与流水对账；调整必须形成业务流水。',permission:'inventory:adjust',columns:[{key:'sku',label:'SKU'},{key:'name',label:'商品'},{key:'available',label:'可用'},{key:'locked',label:'锁定'},{key:'sold',label:'已售'},{key:'status',label:'对账状态'}],rows:[{sku:'SKU-10001-A',name:'桂味荔枝 2.5kg 特级',available:186,locked:12,sold:438,status:'一致'},{sku:'SKU-10004-A',name:'三文鱼中段 500g',available:45,locked:8,sold:162,status:'库存预警'},{sku:'SKU-10003-A',name:'澳门杏仁饼 480g',available:320,locked:5,sold:611,status:'一致'}]},
 order:{description:'查看订单快照、状态机、模拟支付和退款；后台不能任意越过状态机。',permission:'order:read',columns:[{key:'no',label:'订单号'},{key:'user',label:'用户'},{key:'amount',label:'应付金额'},{key:'payment',label:'支付状态'},{key:'status',label:'订单状态'},{key:'created',label:'创建时间'}],rows:[{no:'YGH202607130001',user:'10001 / 王先生',amount:'¥267.80',payment:'待支付',status:'待支付',created:'2026-07-13 00:20'},{no:'YGH202607110032',user:'10003 / 李先生',amount:'¥238.00',payment:'已支付',status:'已完成',created:'2026-07-11 15:42'},{no:'YGH202607080018',user:'10002 / 陈女士',amount:'¥119.00',payment:'已退款',status:'已退款',created:'2026-07-08 09:31'}]},
 wallet:{description:'审计虚拟充值、支付、退款和余额流水；不接入任何真实支付渠道。',permission:'wallet:read',columns:[{key:'ref',label:'流水号'},{key:'user',label:'用户'},{key:'type',label:'业务类型'},{key:'change',label:'变动金额'},{key:'balance',label:'余额'},{key:'created',label:'发生时间'}],rows:[{ref:'WL202607120031',user:'10001',type:'虚拟充值',change:'+¥500.00',balance:'¥1,286.20',created:'2026-07-12 15:30'},{ref:'WL202607110089',user:'10001',type:'订单支付',change:'-¥238.00',balance:'¥786.20',created:'2026-07-11 15:43'},{ref:'WL202607080054',user:'10002',type:'模拟退款',change:'+¥119.00',balance:'¥1,024.20',created:'2026-07-08 10:12'}]},
};const entity=computed(()=>String(route.meta.entity));const config=computed(()=>configs[entity.value]!);const visible=computed(()=>config.value.rows.filter(row=>(status.value==='全部'||row.status===status.value)&&Object.values(row).join(' ').includes(keyword.value)));function action(){ElMessage.info('正式联调后将按权限调用对应服务接口')};</script>
<template><div class="page-head"><div><h1>{{route.meta.title}}</h1><p>{{config.description}}</p></div><div><el-button :icon="Download">导出</el-button><el-button v-if="['user','product'].includes(entity)" type="primary" :icon="Plus" @click="drawer=true">新增{{entity==='user'?'用户':'商品'}}</el-button></div></div><div class="panel filter-row"><el-input v-model="keyword" :prefix-icon="Search" placeholder="输入关键字查询" clearable style="width:280px"/><el-select v-model="status" style="width:140px"><el-option v-for="s in ['全部','正常','已停用','已上架','库存预警','一致','待支付','已完成']" :key="s" :label="s" :value="s"/></el-select><el-button type="primary">查询</el-button><el-button @click="keyword='';status='全部'">重置</el-button></div><section class="panel table-panel"><el-table :data="visible" stripe><el-table-column v-for="col in config.columns" :key="col.key" :prop="col.key" :label="col.label" min-width="130"><template #default="scope"><el-tag v-if="col.key==='status'||col.key==='payment'" size="small" :type="String(scope.row[col.key]).includes('预警')||String(scope.row[col.key]).includes('待')?'warning':String(scope.row[col.key]).includes('停用')||String(scope.row[col.key]).includes('退款')?'danger':'success'">{{scope.row[col.key]}}</el-tag><span v-else>{{scope.row[col.key]}}</span></template></el-table-column><el-table-column label="操作" fixed="right" width="145"><template #default><el-button link type="primary" @click="drawer=true">详情</el-button><el-button link @click="action">更多</el-button></template></el-table-column></el-table><el-pagination background layout="total, sizes, prev, pager, next" :total="visible.length" :page-sizes="[20,50,100]" style="margin-top:16px;justify-content:flex-end"/></section><el-drawer v-model="drawer" :title="`${route.meta.title} · 详情`" size="520"><el-alert title="权限与状态将由服务端再次校验" type="info" :closable="false"/><el-form label-position="top" style="margin-top:20px"><el-form-item v-for="col in config.columns.slice(0,5)" :key="col.key" :label="col.label"><el-input :placeholder="`请输入${col.label}`"/></el-form-item><el-button type="primary" @click="action">保存</el-button></el-form></el-drawer></template>
